// TopBar.js
import React from 'react';
import { useLocation } from 'react-router-dom';
import { Bell, Search, Menu, User, Sun, Moon } from 'lucide-react';

const TopBar = ({ toggleSidebar, toggleDarkMode, darkMode }) => {
  // Utiliser useLocation directement
  let location;

  try {
    // Essayer d'obtenir la location depuis React Router
    location = useLocation();
  } catch (error) {
    // Si erreur (hors Router), utiliser un objet par défaut
    console.warn('useLocation non disponible, utilisation du fallback');
    location = { pathname: '/' };
  }

  // Fonction pour obtenir le titre de la page
  const getPageTitle = () => {
    // Utiliser optional chaining pour éviter les erreurs
    const pathname = location?.pathname || '/dashboard';

    const pageTitles = {
      '/dashboard': 'Tableau de bord',
      '/dashboard/users': 'Gestion des utilisateurs',
      '/dashboard/products': 'Gestion des produits',
      '/dashboard/orders': 'Commandes',
      '/dashboard/analytics': 'Analytique',
      '/dashboard/messages': 'Messages',
      '/dashboard/settings': 'Paramètres',
      '/dashboard/reports': 'Rapports',
      '/dashboard/calendar': 'Calendrier',
      '/dashboard/notifications': 'Notifications',
      '/dashboard/system': 'Système',
      '/dashboard/database': 'Base de données',
      '/dashboard/backup': 'Sauvegarde',
    };

    return pageTitles[pathname] || 'Tableau de bord';
  };

  // Fonction pour obtenir le fil d'Ariane
  const getBreadcrumbs = () => {
    const pathname = location?.pathname || '/dashboard';
    const segments = pathname.split('/').filter(segment => segment);

    if (segments.length === 0) return ['Tableau de bord'];

    const breadcrumbMap = {
      'dashboard': 'Tableau de bord',
      'users': 'Utilisateurs',
      'products': 'Produits',
      'orders': 'Commandes',
      'analytics': 'Analytique',
      'messages': 'Messages',
      'settings': 'Paramètres',
      'reports': 'Rapports',
      'calendar': 'Calendrier',
      'notifications': 'Notifications',
      'system': 'Système',
      'database': 'Base de données',
      'backup': 'Sauvegarde',
    };

    return segments.map(segment => breadcrumbMap[segment] || segment);
  };

  const pageTitle = getPageTitle();
  const breadcrumbs = getBreadcrumbs();

  return (
    <header className="sticky top-0 z-40 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-xl border-b border-neutral-200/50 dark:border-neutral-800/50">
      <div className="px-6 py-4">
        <div className="flex items-center justify-between">
          {/* Left side */}
          <div className="flex items-center space-x-4">
            <button
              onClick={toggleSidebar}
              className="lg:hidden p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
            >
              <Menu className="h-5 w-5 text-neutral-700 dark:text-neutral-300" />
            </button>

            <div>
              <h1 className="text-xl font-bold text-neutral-900 dark:text-white">
                {pageTitle}
              </h1>
              <div className="flex items-center space-x-2 text-sm text-neutral-500 dark:text-neutral-400">
                {breadcrumbs.map((crumb, index) => (
                  <React.Fragment key={index}>
                    <span>{crumb}</span>
                    {index < breadcrumbs.length - 1 && (
                      <span className="text-neutral-300 dark:text-neutral-600">/</span>
                    )}
                  </React.Fragment>
                ))}
              </div>
            </div>
          </div>

          {/* Right side */}
          <div className="flex items-center space-x-3">
            {/* Search */}
            <div className="relative hidden md:block">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-neutral-400" />
              <input
                type="text"
                placeholder="Rechercher..."
                className="pl-10 pr-4 py-2 w-64 rounded-xl bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              />
            </div>

            {/* Dark mode toggle */}
            <button
              onClick={toggleDarkMode}
              className="p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
            >
              {darkMode ? (
                <Sun className="h-5 w-5 text-yellow-500" />
              ) : (
                <Moon className="h-5 w-5 text-neutral-700" />
              )}
            </button>

            {/* Notifications */}
            <button className="relative p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors">
              <Bell className="h-5 w-5 text-neutral-700 dark:text-neutral-300" />
              <span className="absolute -top-1 -right-1 h-5 w-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                3
              </span>
            </button>

            {/* User */}
            <div className="flex items-center space-x-3 pl-3 border-l border-neutral-200 dark:border-neutral-800">
              <div className="h-8 w-8 rounded-full bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center">
                <User className="h-4 w-4 text-white" />
              </div>
              <div className="hidden md:block">
                <p className="text-sm font-medium text-neutral-900 dark:text-white">
                  Enzo Admin
                </p>
                <p className="text-xs text-neutral-500 dark:text-neutral-400">
                  Administrateur
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </header>
  );
};

export default TopBar;
